1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.api.ResumoRequest;
4	import com.loja.checkout.api.ResumoResponse;
5	import com.loja.checkout.model.*;
6	import org.springframework.stereotype.Service;
7	
8	import java.math.BigDecimal;
9	import java.util.Optional;
10	
11	@Service
12	public class CheckoutService {
13	
14	    public ResumoResponse calcularResumo(ResumoRequest request) {
15	        Optional<ResumoResponse> erroResp = validar(request);
16	        if (erroResp.isPresent()) {
17	            throw new ErroCheckout(erroResp.get().erro());
18	        }
19	
20	        BigDecimal subtotalProdutos = calcularSubtotalProdutos(request.itens());
21	
22	        Cupom cupom = request.cupom() != null ? Cupom.valueOf(request.cupom()) : null;
23	        BigDecimal descontoCupom;
24	        if (cupom != null && cupom.ehFretegratis()) {
25	            descontoCupom = BigDecimal.ZERO;
26	        } else {
27	            descontoCupom = cupom != null ? cupom.calcular(subtotalProdutos, request.itens()) : BigDecimal.ZERO;
28	        }
29	
30	        NivelClube nivelClube = NivelClube.valueOf(request.nivelClube());
31	
32	        ModalidadeEntrega modalidade = ModalidadeEntrega.valueOf(request.modalidadeEntrega());
33	        BigDecimal pesoTotal = calcularPesoTotal(request.itens());
34	        BigDecimal frete;
35	        if (nivelClube.temFreteGratis()) {
36	            frete = BigDecimal.ZERO;
37	        } else if (cupom == Cupom.FRETEGRATIS) {
38	            frete = calcularFreteOriginal(modalidade, pesoTotal);
39	        } else {
40	            frete = calcularFreteOriginal(modalidade, pesoTotal);
41	        }
42	
43	        int prazoDias = modalidade.prazoDias;
44	
45	        Regiao regiao = Regiao.valueOf(request.regiao());
46	        BigDecimal produtosComDesconto = subtotalProdutos.subtract(descontoCupom);
47	        BigDecimal imposto = regiao.calcularImposto(produtosComDesconto);
48	
49	        BigDecimal totalPedido = subtotalProdutos.subtract(descontoCupom).add(frete).add(imposto);
50	
51	        FormaPagamento formaPagamento = FormaPagamento.valueOf(request.formaPagamento());
52	        int parcelas = request.getParcelas();
53	
54	        FormaPagamento.ResultadoPagamento resultadoPagamento = formaPagamento.calcular(totalPedido, parcelas);
55	        BigDecimal totalFinal = resultadoPagamento.totalFinal();
56	        BigDecimal ajustePagamento = Arredonda.round(resultadoPagamento.ajuste());
57	        BigDecimal valorParcela = resultadoPagamento.valorParcela();
58	
59	        BigDecimal creditoProximaCompra = nivelClube.calcularCredito(subtotalProdutos);
60	        boolean temBrinde = nivelClube.temBrinde(subtotalProdutos);
61	
62	        if (cupom == Cupom.FRETEGRATIS) {
63	            descontoCupom = Arredonda.round(calcularFreteOriginal(modalidade, pesoTotal));
64	            ajustePagamento = Arredonda.round(ajustePagamento.add(frete.negate()));
65	            totalFinal = Arredonda.round(totalFinal.add(frete.negate()));
66	            valorParcela = Arredonda.round(valorParcela.multiply(totalFinal).divide(resultadoPagamento.totalFinal(), 10, java.math.RoundingMode.HALF_EVEN));
67	        }
68	
69	        return new ResumoResponse(
70	            Arredonda.round(subtotalProdutos),
71	            Arredonda.round(descontoCupom),
72	            Arredonda.round(frete),
73	            prazoDias,
74	            Arredonda.round(imposto),
75	            ajustePagamento,
76	            Arredonda.round(totalFinal),
77	            parcelas,
78	            valorParcela,
79	            creditoProximaCompra,
80	            temBrinde
81	        );
82	    }
83	
84	    private Optional<ResumoResponse> validar(ResumoRequest request) {
85	        if (request.itens() == null || request.itens().isEmpty()) {
86	            return Optional.of(new ResumoResponse(null, null, null, 0, null, null, null, 0, null, null, false) {
87	                public String erro() { return "PEDIDO_INVALIDO"; }
88	            });
89	        }
90	
91	        for (Item item : request.itens()) {
92	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0 ||
93	                item.quantidade() <= 0 ||
94	                item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) < 0) {
